const chooseCurrentLocation=(target:'buyer'|'merchant')=>{if(!navigator.geolocation){notify('خدمة تحديد الموقع غير مدعومة في هذا الهاتف');return}setLocationBusy(true);navigator.geolocation.getCurrentPosition(position=>{const lat=position.coords.latitude,lon=position.coords.longitude;if(target==='buyer'){setSelectedSavedAddressId('');setAddressLatitude(lat);setAddressLongitude(lon)}else{setStoreLatitude(lat);setStoreLongitude(lon)}setLocationBusy(false);notify('تم تحديد الموقع في النموذج')},()=>{setLocationBusy(false);notify('تعذر تحديد الموقع؛ اسمح للتطبيق باستخدام الموقع من إعدادات الهاتف')},{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}
const openGoogleMaps=(target:'buyer'|'merchant')=>{const lat=target==='buyer'?addressLatitude:storeLatitude,lon=target==='buyer'?addressLongitude:storeLongitude;const url=lat!==null&&lon!==null?'https://www.google.com/maps/search/?api=1&query='+lat+','+lon:'https://www.google.com/maps';window.open(url,'_blank','noopener,noreferrer')}
const applyGoogleMapsLocation=(target:'buyer'|'merchant')=>{const raw=mapLocationUrl.trim();if(!raw){notify('الصق رابط الموقع الذي نسخته من خرائط Google');return}const decoded=decodeURIComponent(raw);const patterns=[/[!@]3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/i,/@(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/,/(?:query|q)=(-?\d+(?:\.\d+)?)(?:%2C|,|%20|\s)+(-?\d+(?:\.\d+)?)/i,/(-?\d{1,3}\.\d{3,}),\s*(-?\d{1,3}\.\d{3,})/];let match:RegExpExecArray|null=null;for(const pattern of patterns){match=pattern.exec(decoded);if(match)break}if(!match){notify('لم أجد إحداثيات في الرابط. افتح الموقع المحدد في خرائط Google ثم اختر مشاركة ونسخ الرابط الكامل');return}const lat=Number(match[1]),lon=Number(match[2]);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){notify('إحداثيات الموقع غير صحيحة');return}if(target==='buyer'){setSelectedSavedAddressId('');setAddressLatitude(lat);setAddressLongitude(lon)}else{setStoreLatitude(lat);setStoreLongitude(lon)}setMapLocationUrl('');notify('تم استيراد موقع خرائط Google. احفظ العنوان أو موقع المتجر لإتمام الحفظ')}
const submitProductReview=async(product:Product)=>{if(!supabase||!authUser){notify('سجّل الدخول لتقييم المنتج');return}if(!product.dbId){notify('لا يمكن تقييم منتج تجريبي');return}setReviewBusy(true);try{const uid=(authUser as any).id;const {data:items,error:itemError}=await supabase.from('order_items').select('id,orders!inner(buyer_id,status)').eq('product_id',product.dbId).eq('orders.buyer_id',uid).eq('orders.status','delivered').limit(30);if(itemError)throw itemError;if(!items?.length)throw new Error('يمكنك تقييم المنتج بعد استلامه فقط');const {data:reviews,error:reviewLookupError}=await supabase.from('product_reviews').select('order_item_id').in('order_item_id',items.map((row:any)=>row.id));if(reviewLookupError)throw reviewLookupError;const reviewed=new Set((reviews||[]).map((row:any)=>row.order_item_id));const item=items.find((row:any)=>!reviewed.has(row.id));if(!item)throw new Error('لقد قيّمت جميع مشترياتك السابقة من هذا المنتج');const {error}=await supabase.from('product_reviews').insert({product_id:product.dbId,user_id:uid,order_item_id:item.id,rating:reviewRating,review_text:reviewText.trim()});if(error)throw error;setCatalog(rows=>rows.map(row=>row.id===product.id?{...row,rating:((row.rating*row.reviews)+reviewRating)/(row.reviews+1),reviews:row.reviews+1,reviewEntries:[{name:profileFullName||'أنت',rating:reviewRating,text:reviewText.trim(),createdAt:new Date().toISOString()},...(row.reviewEntries||[])]}:row));setSelected(current=>current&&current.id===product.id?{...current,rating:((current.rating*current.reviews)+reviewRating)/(current.reviews+1),reviews:current.reviews+1,reviewEntries:[{name:profileFullName||'أنت',rating:reviewRating,text:reviewText.trim(),createdAt:new Date().toISOString()},...(current.reviewEntries||[])]}:current);setReviewText('');setReviewModalOpen(false);notify('شكراً لك، تم إرسال تقييمك وسيظهر بعد اعتماده');}catch(error){notify(error instanceof Error?error.message:'تعذر إرسال التقييم')}finally{setReviewBusy(false)}}
